-- Fase 2C: administración trazable de jornadas. Las operaciones de escritura
-- se mantienen fuera del DML directo del navegador y siempre reciben la
-- organización desde la jornada almacenada, nunca desde el cliente.
begin;

alter table public.work_session_audit_log
  add column if not exists reason text,
  add column if not exists previous_values jsonb,
  add column if not exists next_values jsonb,
  add column if not exists resulting_revision integer;

do $$
declare r record;
begin
  -- The original inline CHECK names are generated by PostgreSQL. Remove only
  -- the status/action checks introduced in 2A, preserving unrelated checks.
  for r in
    select conname
    from pg_constraint
    where conrelid = 'public.work_sessions'::regclass
      and contype = 'c'
      and pg_get_constraintdef(oid) like '%status = ''open''%'
  loop
    execute format('alter table public.work_sessions drop constraint %I', r.conname);
  end loop;
  for r in
    select conname
    from pg_constraint
    where conrelid = 'public.work_session_audit_log'::regclass
      and contype = 'c'
      and pg_get_constraintdef(oid) like '%clocked_in%'
  loop
    execute format('alter table public.work_session_audit_log drop constraint %I', r.conname);
  end loop;
end;
$$;

alter table public.work_sessions
  add constraint work_sessions_status_timing_check check (
    (status = 'open' and clock_out_at is null)
    or (status = 'closed' and clock_out_at is not null and clock_out_at >= clock_in_at)
    -- A void preserves the original evidence. It intentionally accepts the
    -- prior open/closed timestamp shape and therefore no longer blocks a new
    -- legitimate open session for that worker.
    or (status = 'voided' and (clock_out_at is null or clock_out_at >= clock_in_at))
  );

alter table public.work_session_audit_log
  add constraint work_session_audit_log_action_check check (action in (
    'clocked_in', 'clocked_out', 'clock_in_rejected_open', 'clock_out_rejected_no_open',
    'admin_corrected', 'admin_closed', 'voided'
  ));

create index if not exists work_sessions_organization_status_clock_in_idx
  on public.work_sessions(organization_id, status, clock_in_at desc);
create index if not exists work_session_audit_session_occurred_idx
  on public.work_session_audit_log(work_session_id, occurred_at desc);

-- Read functions deliberately remain SECURITY INVOKER: the 2A RLS policies
-- are the authorization boundary for owner/admin and personal employee reads.
create or replace function public.admin_list_work_sessions(
  p_worker_id uuid default null,
  p_from date default null,
  p_to date default null,
  p_status text default null,
  p_limit integer default 100
)
returns table (
  session_id uuid,
  organization_id uuid,
  worker_id uuid,
  employee_code text,
  first_name text,
  last_name text,
  clock_in_at timestamptz,
  clock_out_at timestamptz,
  status text,
  revision integer,
  created_at timestamptz,
  updated_at timestamptz
)
language sql stable security invoker
set search_path = public
as $$
  select s.id, s.organization_id, s.worker_id, w.employee_code, w.first_name,
         w.last_name, s.clock_in_at, s.clock_out_at, s.status, s.revision,
         s.created_at, s.updated_at
  from public.work_sessions s
  join public.workers w on w.id = s.worker_id
  where (p_worker_id is null or s.worker_id = p_worker_id)
    and (p_from is null or s.clock_in_at >= p_from::timestamptz)
    and (p_to is null or s.clock_in_at < (p_to + 1)::timestamptz)
    and (p_status is null or s.status = p_status)
  order by s.clock_in_at desc
  limit greatest(1, least(coalesce(p_limit, 100), 200));
$$;

create or replace function public.admin_list_work_session_audit(p_work_session_id uuid)
returns table (
  audit_id bigint,
  work_session_id uuid,
  actor_id uuid,
  action text,
  reason text,
  previous_values jsonb,
  next_values jsonb,
  resulting_revision integer,
  occurred_at timestamptz
)
language sql stable security invoker
set search_path = public
as $$
  select a.id, a.work_session_id, a.actor_id, a.action, a.reason,
         a.previous_values, a.next_values, a.resulting_revision, a.occurred_at
  from public.work_session_audit_log a
  where a.work_session_id = p_work_session_id
  order by a.id asc;
$$;

-- authenticated has no UPDATE on work_sessions. This narrowly scoped
-- SECURITY DEFINER implementation is therefore necessary for the controlled
-- write. It derives the actor from auth.uid(), locks the actual row, checks
-- its organisation role, and records the correction in the same transaction.
create or replace function priteca_private.admin_update_work_session_impl(
  p_work_session_id uuid,
  p_expected_revision integer,
  p_operation text,
  p_changes jsonb,
  p_reason text
)
returns public.work_sessions
language plpgsql security definer
set search_path = pg_catalog, public, priteca_private
as $$
declare
  v_actor uuid;
  v_session public.work_sessions;
  v_result public.work_sessions;
  v_reason text;
  v_clock_in timestamptz;
  v_clock_out timestamptz;
  v_before jsonb;
  v_after jsonb;
  v_key text;
begin
  v_actor := priteca_private.request_actor_id();
  if v_actor is null then
    raise exception 'No autorizado.' using errcode = '42501';
  end if;
  if p_work_session_id is null or p_expected_revision is null or p_expected_revision < 1
     or p_operation not in ('correct', 'close_forgotten', 'void') then
    raise exception 'Entrada inválida.' using errcode = '22023';
  end if;
  v_reason := btrim(coalesce(p_reason, ''));
  if char_length(v_reason) not between 3 and 500 then
    raise exception 'El motivo debe tener entre 3 y 500 caracteres.' using errcode = '22023';
  end if;

  select s.* into v_session
  from public.work_sessions s
  where s.id = p_work_session_id
  for update;
  if not found or not public.is_organization_admin(v_session.organization_id)
     or v_session.revision <> p_expected_revision then
    raise exception 'Conflicto o jornada inaccesible.' using errcode = '40001';
  end if;
  if v_session.status = 'voided' then
    raise exception 'La jornada anulada no puede modificarse.' using errcode = '22023';
  end if;

  v_before := jsonb_build_object(
    'clock_in_at', v_session.clock_in_at,
    'clock_out_at', v_session.clock_out_at,
    'status', v_session.status,
    'revision', v_session.revision
  );

  if p_operation = 'correct' then
    if p_changes is null or jsonb_typeof(p_changes) <> 'object' or p_changes = '{}'::jsonb then
      raise exception 'La corrección debe incluir una hora.' using errcode = '22023';
    end if;
    for v_key in select jsonb_object_keys(p_changes) loop
      if v_key not in ('clock_in_at', 'clock_out_at') then
        raise exception 'Campo de jornada no permitido.' using errcode = '22023';
      end if;
      if jsonb_typeof(p_changes -> v_key) <> 'string' then
        raise exception 'La fecha debe ser una cadena ISO válida.' using errcode = '22023';
      end if;
    end loop;
    begin
      v_clock_in := case when p_changes ? 'clock_in_at' then (p_changes ->> 'clock_in_at')::timestamptz else v_session.clock_in_at end;
      v_clock_out := case when p_changes ? 'clock_out_at' then (p_changes ->> 'clock_out_at')::timestamptz else v_session.clock_out_at end;
    exception when invalid_datetime_format or datetime_field_overflow then
      raise exception 'La fecha de jornada no es válida.' using errcode = '22023';
    end;
    if v_clock_out is not null and v_clock_out < v_clock_in then
      raise exception 'La salida no puede ser anterior a la entrada.' using errcode = '22023';
    end if;
    if v_clock_in is not distinct from v_session.clock_in_at
       and v_clock_out is not distinct from v_session.clock_out_at then
      raise exception 'La corrección no cambia la jornada.' using errcode = '22023';
    end if;
    update public.work_sessions
    set clock_in_at = v_clock_in,
        clock_out_at = v_clock_out,
        status = case when v_clock_out is null then 'open' else 'closed' end
    where id = v_session.id
    returning * into v_result;

  elsif p_operation = 'close_forgotten' then
    if v_session.status <> 'open' or p_changes is null
       or jsonb_typeof(p_changes) <> 'object'
       or not (p_changes ? 'clock_out_at')
       or exists (select 1 from jsonb_object_keys(p_changes) as k where k <> 'clock_out_at') then
      raise exception 'Solo una jornada abierta puede cerrarse con una salida indicada.' using errcode = '22023';
    end if;
    if jsonb_typeof(p_changes -> 'clock_out_at') <> 'string' then
      raise exception 'La salida debe ser una fecha ISO válida.' using errcode = '22023';
    end if;
    begin
      v_clock_out := (p_changes ->> 'clock_out_at')::timestamptz;
    exception when invalid_datetime_format or datetime_field_overflow then
      raise exception 'La salida no es válida.' using errcode = '22023';
    end;
    if v_clock_out < v_session.clock_in_at then
      raise exception 'La salida no puede ser anterior a la entrada.' using errcode = '22023';
    end if;
    update public.work_sessions
    set clock_out_at = v_clock_out, status = 'closed', clock_out_actor_id = v_actor
    where id = v_session.id
    returning * into v_result;

  else
    if p_changes is not null and p_changes <> '{}'::jsonb then
      raise exception 'La anulación no admite cambios de hora.' using errcode = '22023';
    end if;
    update public.work_sessions set status = 'voided'
    where id = v_session.id
    returning * into v_result;
  end if;

  v_after := jsonb_build_object(
    'clock_in_at', v_result.clock_in_at,
    'clock_out_at', v_result.clock_out_at,
    'status', v_result.status,
    'revision', v_result.revision
  );
  insert into public.work_session_audit_log (
    organization_id, worker_id, work_session_id, actor_id, action, reason,
    previous_values, next_values, resulting_revision
  ) values (
    v_result.organization_id, v_result.worker_id, v_result.id, v_actor,
    case p_operation when 'correct' then 'admin_corrected'
                     when 'close_forgotten' then 'admin_closed' else 'voided' end,
    v_reason, v_before, v_after, v_result.revision
  );
  return v_result;
end;
$$;
alter function priteca_private.admin_update_work_session_impl(uuid, integer, text, jsonb, text) owner to postgres;
revoke all on function priteca_private.admin_update_work_session_impl(uuid, integer, text, jsonb, text) from public, anon, authenticated;
grant execute on function priteca_private.admin_update_work_session_impl(uuid, integer, text, jsonb, text) to authenticated;

create or replace function public.admin_update_work_session_with_revision(
  p_work_session_id uuid,
  p_expected_revision integer,
  p_operation text,
  p_changes jsonb default '{}'::jsonb,
  p_reason text default null
)
returns public.work_sessions
language sql security invoker
set search_path = public, priteca_private
as $$
  select priteca_private.admin_update_work_session_impl(
    p_work_session_id, p_expected_revision, p_operation, p_changes, p_reason
  );
$$;
revoke all on function public.admin_update_work_session_with_revision(uuid, integer, text, jsonb, text) from public, anon;
grant execute on function public.admin_update_work_session_with_revision(uuid, integer, text, jsonb, text) to authenticated;

revoke all on function public.admin_list_work_sessions(uuid, date, date, text, integer) from public, anon;
revoke all on function public.admin_list_work_session_audit(uuid) from public, anon;
grant execute on function public.admin_list_work_sessions(uuid, date, date, text, integer) to authenticated;
grant execute on function public.admin_list_work_session_audit(uuid) to authenticated;

notify pgrst, 'reload schema';
commit;
